<?php $title='Rules & Groups'; ?>
<div class="page-head"><div><span class="eyebrow">TARGETING</span><h1>Rules &amp; Groups</h1><p>Thứ tự quyết định: kill switch → user cụ thể → group → rollout ổn định → mặc định.</p></div></div>
<?php if(!$isTestEnvironment): ?><div class="notice info">Môi trường phát hành đang ở chế độ chỉ xem. Hãy chuyển sang Staging để chỉnh sửa rule và nhóm.</div><?php endif; ?>
<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Quy tắc theo feature</h2><p>Thứ tự ưu tiên nhỏ hơn được áp dụng trước.</p></div></div><?php foreach($flags as $flag): ?><div class="rule-card"><div class="rule-title"><strong><?= e($flag['name']) ?></strong><code><?= e($flag['key']) ?></code></div><?php if($flag['rules']): ?><div class="table-wrap"><table><thead><tr><th>Ưu tiên</th><th>Đối tượng</th><th>Hiệu lực</th><th></th></tr></thead><tbody><?php foreach($flag['rules'] as $rule): ?><tr><td><?= (int)$rule['priority'] ?></td><td><?= e($rule['target_type']) ?><?= $rule['target_type']==='group'?' · nhóm #'.(int)$rule['target_group_id']:'' ?></td><td><?= e($rule['effect']) ?></td><td><?php if($flag['can_edit']): ?><form method="post" action="<?= e(url('rules/delete')) ?>"><?= csrf_field() ?><input type="hidden" name="rule_id" value="<?= (int)$rule['id'] ?>"><button class="link danger" type="submit">Xóa</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">Chưa có rule. Default/rollout sẽ được dùng.</p><?php endif; ?><?php if($flag['can_edit']): ?><details class="details-form"><summary>Thêm rule</summary><form method="post" action="<?= e(url('rules/store')) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="flag_id" value="<?= (int)$flag['id'] ?>"><label>Loại đối tượng<select name="target_type"><option value="user">User cụ thể</option><option value="group">Nhóm</option></select></label><label>Hiệu lực<select name="effect"><option value="on">Bật</option><option value="off">Tắt</option></select></label><label>Ưu tiên<input type="number" name="priority" value="100" min="0" max="100000"></label><label>Group ID<select name="target_group_id"><option value="">—</option><?php foreach($groups as $group): ?><option value="<?= (int)$group['id'] ?>"><?= e($group['name']) ?> (<?= e($group['key']) ?>)</option><?php endforeach; ?></select></label><label class="wide">User IDs (phân cách dấu phẩy / dòng mới)<textarea name="user_ids" rows="2" placeholder="USER_0001, USER_0002"></textarea></label><label class="wide">Lý do<input name="reason" placeholder="Lý do thay đổi"></label><button class="button" type="submit">Thêm rule vào nháp</button></form></details><?php else: ?><span class="pill gray">Chỉ xem</span><?php endif; ?></div><?php endforeach; ?></section>
<section class="panel"><div class="panel-head"><div><h2>Nhóm người dùng</h2><p>Thành viên nhóm được chụp vào snapshot khi phát hành.</p></div></div><?php foreach($groups as $group): ?><div class="group-row"><div><strong><?= e($group['name']) ?></strong><small><code><?= e($group['key']) ?></code> · <?= (int)$group['member_count'] ?> thành viên</small></div><?php if($isTestEnvironment && App\Support\Auth::isAdmin($projectId)): ?><details><summary>Thêm IDs</summary><form method="post" action="<?= e(url('groups/members')) ?>"><?= csrf_field() ?><input type="hidden" name="group_id" value="<?= (int)$group['id'] ?>"><textarea name="members" rows="3" placeholder="USER_0001, USER_0002"></textarea><button class="button small">Thêm</button></form></details><?php endif; ?></div><?php endforeach; ?><?php if($isTestEnvironment && App\Support\Auth::isAdmin($projectId)): ?><details class="details-form"><summary>Tạo nhóm</summary><form method="post" action="<?= e(url('groups/create')) ?>" class="form-grid"><?= csrf_field() ?><label>Key<input name="key" required pattern="[a-z][a-z0-9_]{1,99}"></label><label>Tên nhóm<input name="name" required></label><label class="wide">User IDs<textarea name="members" rows="3"></textarea></label><button class="button" type="submit">Tạo nhóm</button></form></details><?php endif; ?></section></div>
